"""A plain wooden shipping crate of nailed planks with darker corner battens and a plank lid (generated by npm run new)."""
import random

from propsmith import prop
from propsmith.materials import material
from propsmith.shapes import box, cylinder

TILE = 1.5  # metres per tile
# Overall size: about 0.75 m on each side (the footprint is 1x1 tile = 1.5 x 1.5 m, height 0.55 tile = 0.825 m).
S = 0.75  # outer width and depth, battens included
H = 0.75  # overall height, lid included
BT = 0.025  # batten thickness
BW = 0.075  # batten width
BH = 0.075  # height of the top and bottom rim battens
C = S / 2 - BT  # half-size of the plank box under the battens
T = 0.022  # wall plank thickness
LID_T = 0.03  # lid plank thickness
WALL_H = H - LID_T  # walls and battens stop under the lid
PLANKS = 3  # wall planks per face
LID_PLANKS = 4
GAP = 0.007  # gap between planks
NAIL_R, NAIL_H = 0.008, 0.004

WOOD = (0.25, 0.165, 0.09)  # linear RGB
WOOD_OLD = (0.21, 0.15, 0.095)
BATTEN = (0.11, 0.068, 0.04)
INSIDE = (0.08, 0.055, 0.035)
IRON = (0.05, 0.048, 0.045)

# Face directions: (outward normal x, y), the rotation that turns +z to it.
FACES = (((0, -1), (90, 0, 0)), ((0, 1), (-90, 0, 0)), ((1, 0), (0, 90, 0)), ((-1, 0), (0, -90, 0)))


@prop
def crate_wood():
    rnd = random.Random(7)
    wood = material("crate_planks", WOOD, vary=0.25, scale=14)
    old = material("crate_planks_old", WOOD_OLD, vary=0.3, scale=11)
    batten = material("crate_battens", BATTEN, vary=0.25, scale=12)
    inside = material("crate_inside", INSIDE, vary=0.1, scale=4, crevice=0.2)
    iron = material("crate_nails", IRON, rough=0.5, metal=0.7)

    # A dark inner box so the gaps between planks show shadow, not the far side.
    box("inside", (2 * (C - T), 2 * (C - T), WALL_H - 0.02), (0, 0, WALL_H / 2), inside, bevel=0)

    ph = WALL_H / PLANKS
    for f, ((nx, ny), nail_rot) in enumerate(FACES):
        along_x = nx == 0
        # Planks: the -y/+y faces run the full width, the x faces fit between them.
        length = 2 * C if along_x else 2 * (C - T)
        for k in range(PLANKS):
            h = ph - GAP + rnd.uniform(-0.004, 0.002)
            z = ph * (k + 0.5) + rnd.uniform(-0.002, 0.002)
            off = C - T / 2 + rnd.uniform(-0.002, 0.002)
            mat = old if rnd.random() < 0.35 else wood
            tilt = rnd.uniform(-0.5, 0.5)
            if along_x:
                box(f"plank_{f}_{k}", (length, T, h), (rnd.uniform(-0.004, 0.004), ny * off, z), mat,
                    rot=(0, tilt, 0), bevel=0.006)
            else:
                box(f"plank_{f}_{k}", (T, length, h), (nx * off, rnd.uniform(-0.004, 0.004), z), mat,
                    rot=(tilt, 0, 0), bevel=0.006)

        # Battens: vertical at both corners, rims along the bottom and the top.
        if along_x:
            edge = C + BT - BW / 2  # these cover the ends of the x faces' battens
            span = 2 * (C + BT - BW)
            y = ny * (C + BT / 2)
            for s in (-1, 1):
                box(f"post_{f}_{s}", (BW, BT, WALL_H), (s * edge, y, WALL_H / 2), batten,
                    rot=(0, 0, rnd.uniform(-0.4, 0.4)), bevel=0.008)
            for r, z in (("lo", BH / 2), ("hi", WALL_H - BH / 2)):
                box(f"rim_{f}_{r}", (span, BT * 0.9, BH), (0, y, z + rnd.uniform(-0.003, 0.003)), batten, bevel=0.008)
        else:
            edge = C - BW / 2
            span = 2 * (C - BW)
            x = nx * (C + BT / 2)
            for s in (-1, 1):
                box(f"post_{f}_{s}", (BT, BW, WALL_H), (x, s * edge, WALL_H / 2), batten,
                    rot=(0, 0, rnd.uniform(-0.4, 0.4)), bevel=0.008)
            for r, z in (("lo", BH / 2), ("hi", WALL_H - BH / 2)):
                box(f"rim_{f}_{r}", (BT * 0.9, span, BH), (x, 0, z + rnd.uniform(-0.003, 0.003)), batten, bevel=0.008)

        # Nails: three down each corner post, one in each rim end.
        out = C + BT
        for s in (-1, 1):
            for z in (BH / 2, WALL_H / 2, WALL_H - BH / 2):
                a = s * (out - BW / 2 if along_x else C - BW / 2)
                at = (a, ny * out, z) if along_x else (nx * out, a, z)
                cylinder(f"nail_{f}_{s}_{z:.2f}", NAIL_R, NAIL_H, at, iron, segments=6, rot=nail_rot, bevel=0)

    # The lid: planks across x, slightly uneven, nailed at both ends.
    lw = S / LID_PLANKS
    for i in range(LID_PLANKS):
        y = -S / 2 + lw * (i + 0.5)
        t = LID_T - rnd.uniform(0, 0.004)
        mat = old if rnd.random() < 0.35 else wood
        box(f"lid_{i}", (S - rnd.uniform(0, 0.01), lw - GAP, t),
            (rnd.uniform(-0.003, 0.003), y + rnd.uniform(-0.002, 0.002), WALL_H + t / 2), mat,
            rot=(0, 0, rnd.uniform(-0.6, 0.6)), bevel=0.007)
        for s in (-1, 1):
            cylinder(f"lid_nail_{i}_{s}", NAIL_R, NAIL_H, (s * (S / 2 - BW / 2), y, WALL_H + t - 0.001), iron,
                     segments=6, bevel=0)
